window.__votdWeek && window.__votdWeek({"week":"2029-03-12","reading":"Doctrine and Covenants 20–22","days":[{"d":"2029-03-12","ref":"D&C 20:12","b":"D&C","c":20,"v":12,"he":"וּבָזֶה מוֹרֶה כִּי הוּא הוּא אֱלֹהִים אֶתְמוֹל הַיּוֹם וּלְעוֹלָם אָמֵן׃","en":"Thereby showing that he is the same God yesterday, today, and forever. Amen."},{"d":"2029-03-13","ref":"D&C 20:19","b":"D&C","c":20,"v":19,"he":"וַיִּתֵּן לָהֶם מִצְוֹת לְאַהֲבָה אוֹתוֹ וּלְעׇבְדוֹ הוּא הָאֱלֹהִים הַחַי וְהָאֱמֶת לְבַדּוֹ וְהוּא לְבַדּוֹ יִהְיֶה אֲשֶׁר יִשְׁתַּחֲווּ לוֹ׃","en":"And gave unto them commandments that they should love and serve him, the only living and true God, and that he should be the only being whom they should worship."},{"d":"2029-03-14","ref":"D&C 20:83","b":"D&C","c":20,"v":83,"he":"וְגַם אִם גֹּרְשׁוּ אֲנָשִׁים מִן הַכְּנֵסִיָּה לְמַעַן יִמָּחוּ שְׁמוֹתֵיהֶם מִסֵּפֶר הַשֵּׁמוֹת הַגָּדוֹל אֲשֶׁר לַכְּנֵסִיָּה׃","en":"And also, if any have been expelled from the church, so that their names may be blotted out of the general church record of names."},{"d":"2029-03-15","ref":"D&C 21:4","b":"D&C","c":21,"v":4,"he":"וְלָכֵן תִּקְשִׁיב הַכְּנֵסִיָּה לְכׇל־דְּבָרָיו וּמִצְוֹתָיו אֲשֶׁר יִתֵּן לָכֶם כַּאֲשֶׁר יְקַבְּלֵם מִמֶּנִּי מִתְהַלֵּךְ בְּכׇל־קְדֻשָּׁה לְפָנָי׃","en":"Wherefore, meaning the church, thou shalt give heed unto all his words and commandments which he shall give unto you as he receiveth them, walking in all holiness before me;"},{"d":"2029-03-16","ref":"D&C 21:5","b":"D&C","c":21,"v":5,"he":"כִּי אֶת־דְּבָרוֹ תְּקַבְּלוּ כְּמִפִּי בְּכׇל־אֹרֶךְ־אַפַּיִם וֶאֱמוּנָה׃","en":"For his word ye shall receive, as if from mine own mouth, in all patience and faith."},{"d":"2029-03-17","ref":"D&C 21:6","b":"D&C","c":21,"v":6,"he":"כִּי בַּעֲשׂוֹתְכֶם זֹאת שַׁעֲרֵי שְׁאוֹל לֹא יִגְבְּרוּ עֲלֵיכֶם אָכֵן וַיהוָה אֱלֹהִים יָפִיץ כֹּחוֹת הַחֹשֶׁךְ מִלְּפָנֵיכֶם וְיָנִיעַ אֶת־הַשָּׁמַיִם לְטוֹבַתְכֶם וְלִכְבוֹד שְׁמוֹ׃","en":"For by doing these things the gates of hell shall not prevail against you; yea, and the Lord God will disperse the powers of darkness from before you, and cause the heavens to shake for your good, and his name's glory."},{"d":"2029-03-18","ref":"D&C 22:4","b":"D&C","c":22,"v":4,"he":"לָכֵן בֹּאוּ בַּשַּׁעַר כַּאֲשֶׁר צִוִּיתִי וְאַל־תְּבַקְשׁוּ לָעוּץ אֶת־אֱלֹהֵיכֶם אָמֵן׃","en":"Wherefore, enter ye in at the gate, as I have commanded, and seek not to counsel your God. Amen."}]});
